<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_permission('nursing_notes.manage');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$patient=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT);$type=(string)($_POST['note_type']??'');$note=trim((string)($_POST['note']??''));$types=['observation','vital_signs','medication_administered','care'];$vitals=[];
    foreach(['temperature_c'=>['temperature',50],'pulse_bpm'=>['pulse',300],'respiratory_rate'=>['respiratory_rate',100],'systolic_bp'=>['systolic',400],'diastolic_bp'=>['diastolic',300],'oxygen_saturation'=>['oxygen',100]] as $column=>$spec){$raw=trim((string)($_POST[$spec[0]]??''));$v=$raw===''?null:($column==='temperature_c'?filter_var($raw,FILTER_VALIDATE_FLOAT):filter_var($raw,FILTER_VALIDATE_INT));if($raw!==''&&($v===false||$v<0||$v>$spec[1])){set_flash('danger','Check the vital sign values.');redirect('/hospital%20management/nursing/index.php');}$vitals[$column]=$v;}
    if(!$patient||!in_array($type,$types,true)||$note===''||strlen($note)>10000){set_flash('danger','Choose an admitted patient, note type, and enter a note.');redirect('/hospital%20management/nursing/index.php');}
    $check=$pdo->prepare("SELECT id FROM admissions WHERE patient_id=:patient AND status='admitted'");$check->execute(['patient'=>$patient]);if(!$check->fetch()){set_flash('danger','Nursing notes can be added for currently admitted patients.');redirect('/hospital%20management/nursing/index.php');}
    $q=$pdo->prepare('INSERT INTO nursing_notes(patient_id,recorded_by,note_type,note,temperature_c,pulse_bpm,respiratory_rate,systolic_bp,diastolic_bp,oxygen_saturation) VALUES(:patient,:user,:type,:note,:temperature_c,:pulse_bpm,:respiratory_rate,:systolic_bp,:diastolic_bp,:oxygen_saturation)');$q->execute(array_merge(['patient'=>$patient,'user'=>current_user()['id'],'type'=>$type,'note'=>$note],$vitals));$id=(string)$pdo->lastInsertId();record_audit('create','nursing_note',$id,'Nursing observation recorded');notify_staff('nursing_note_recorded','nursing_note',$id,current_user()['full_name'].' recorded a nursing observation.');set_flash('success','Nursing note saved.');redirect('/hospital%20management/nursing/index.php');
}
$admitted=$pdo->query("SELECT DISTINCT p.id,p.patient_no,p.first_name,p.last_name,w.name AS ward_name,b.bed_number FROM admissions a JOIN patients p ON p.id=a.patient_id JOIN beds b ON b.id=a.bed_id JOIN wards w ON w.id=b.ward_id WHERE a.status='admitted' ORDER BY w.name,b.bed_number")->fetchAll();
$notes=$pdo->query("SELECT n.*,p.patient_no,p.first_name,p.last_name,u.full_name AS nurse FROM nursing_notes n JOIN patients p ON p.id=n.patient_id JOIN users u ON u.id=n.recorded_by JOIN admissions a ON a.patient_id=p.id AND a.status='admitted' ORDER BY n.recorded_at DESC LIMIT 200")->fetchAll();
$pageTitle='Nursing and ward records';require __DIR__.'/../includes/header.php'; ?>
<div class="page-heading"><div><h2>Nursing and ward records</h2><p>Chart patient observations, vital signs, care, and medicines administered.</p></div></div>
<section class="content-card form-card mt-0"><div class="card-heading"><h3>Record ward observation</h3></div><form method="post" class="row g-3"><?= csrf_field() ?><div class="col-md-4"><label class="form-label">Admitted patient</label><select class="form-select" name="patient_id" required><option value="">Select ward patient</option><?php foreach($admitted as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['ward_name'].' · '.$p['bed_number'].' · '.$p['patient_no'].' · '.$p['last_name'].', '.$p['first_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Record type</label><select class="form-select" name="note_type" required><?php foreach(['observation'=>'Observation','vital_signs'=>'Vital signs','care'=>'Nursing care','medication_administered'=>'Medicine administered'] as $k=>$v): ?><option value="<?= e($k) ?>"><?= e($v) ?></option><?php endforeach; ?></select></div><div class="col-md-5"><label class="form-label">Note</label><input class="form-control" name="note" maxlength="10000" required></div><div class="col-md-2"><label class="form-label">Temperature °C</label><input class="form-control" type="number" name="temperature" min="0" max="50" step="0.1"></div><div class="col-md-2"><label class="form-label">Pulse / min</label><input class="form-control" type="number" name="pulse" min="0" max="300"></div><div class="col-md-2"><label class="form-label">Resp. / min</label><input class="form-control" type="number" name="respiratory_rate" min="0" max="100"></div><div class="col-md-2"><label class="form-label">Systolic BP</label><input class="form-control" type="number" name="systolic" min="0" max="400"></div><div class="col-md-2"><label class="form-label">Diastolic BP</label><input class="form-control" type="number" name="diastolic" min="0" max="300"></div><div class="col-md-2"><label class="form-label">Oxygen %</label><input class="form-control" type="number" name="oxygen" min="0" max="100"></div><div class="col-12"><button class="btn btn-primary">Save nursing record</button></div></form></section>
<section class="content-card"><div class="card-heading"><h3>Current inpatient notes</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>Patient</th><th>Type</th><th>Note</th><th>Vital signs</th><th>Recorded by</th></tr></thead><tbody><?php if(!$notes): ?><tr><td class="empty-state" colspan="6">No inpatient notes recorded.</td></tr><?php else: foreach($notes as $n): ?><tr><td><?= e(date('M j, Y g:i a',strtotime($n['recorded_at']))) ?></td><td><?= e($n['last_name'].', '.$n['first_name']) ?><br><span class="subtle"><?= e($n['patient_no']) ?></span></td><td><?= e(ucwords(str_replace('_',' ',$n['note_type']))) ?></td><td><?= nl2br(e($n['note'])) ?></td><td><?= e('Temp '.($n['temperature_c']??'—').'°C · Pulse '.($n['pulse_bpm']??'—').' · BP '.($n['systolic_bp']??'—').'/'.($n['diastolic_bp']??'—').' · SpO₂ '.($n['oxygen_saturation']??'—').'%') ?></td><td><?= e($n['nurse']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
